settings.custom_liquid:
{% assign current_lang = localization.language.iso_code | default: shop.locale | slice: 0,2 | downcase %}
{% if current_lang != 'es' %}{% assign current_lang = 'en' %}{% endif %}

<style>
  :root,[class*="color-scheme"]{--color-background:rgb(0 0 0 / 1)!important;--color-background-rgb:0,0,0!important;--color-background-contrast:rgb(0 0 0 / 1)!important;}
  html,body{background:#000!important;background-color:#000!important;}
  .shopify-section,.section-wrapper,.section,main,#MainContent,footer,.footer,[class*="color-scheme"]{background:#000!important;background-color:#000!important;}
  .shopify-section-header,.shopify-section-header>*,.shopify-section-header *[class*="color-scheme"],#header-group,#header-group>*,#header-group *[class*="color-scheme"],header-component,header-component *[class*="color-scheme"],#header-component,#header-component *[class*="color-scheme"],.header-section,.header-section *[class*="color-scheme"],header,header[class*="color-scheme"]{background:transparent!important;background-color:transparent!important;--color-background:rgb(0 0 0 / 0)!important;--color-background-rgb:0,0,0!important;border-color:transparent!important;}
</style>

<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@400;600;700;900&family=Inter:wght@300;400;500;600;800&display=swap" rel="stylesheet">

<section id="cruiseHero-{{ section.id }}" class="cruise-hero" aria-label="Cruise Hero" data-lang="{{ current_lang }}">
  <div class="cruise-wrap">

    <!-- Badges -->
    <div class="cruise-badges" data-step="1">
      {% if current_lang == 'es' %}
      <div class="cruise-badge-slot">
        <span class="cruise-badge cruise-badge--active"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l7 4v6c0 5-3.5 9-7 10-3.5-1-7-5-7-10V6l7-4z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Licenciado y Asegurado</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 12l2 2 4-4m5.5 2a9.5 9.5 0 11-19 0 9.5 9.5 0 0119 0z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Choferes Verificados</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 10h18M5 6h14a2 2 0 012 2v10a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Pagos Seguros</span></span>
      </div>
      <div class="cruise-badge-slot">
        <span class="cruise-badge cruise-badge--active"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="1.6" fill="none"/><path d="M12 6v6l4 2" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Servicio 24/7</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13 2L3 14h7l-1 8 10-12h-7l1-8z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Respuesta Rapida</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 22s8-4 8-12V5l-8-3-8 3v5c0 8 8 12 8 12z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">100% Seguro</span></span>
      </div>
      <div class="cruise-badge-slot">
        <span class="cruise-badge cruise-badge--active"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l3 7 7 .6-5.3 4.6L18.6 22 12 18l-6.6 4 1.9-7.2L2 9.6 9 9l3-7z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">5 Estrellas</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2M12 11a4 4 0 100-8 4 4 0 000 8z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Choferes Expertos</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l2.5 5.5L20 8.5l-4 4 1 5.5-5-3-5 3 1-5.5-4-4 5.5-1L12 2z" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linejoin="round"/></svg><span class="badge-text">Calidad Premium</span></span>
      </div>
      {% else %}
      <div class="cruise-badge-slot">
        <span class="cruise-badge cruise-badge--active"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l7 4v6c0 5-3.5 9-7 10-3.5-1-7-5-7-10V6l7-4z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Licensed &amp; Insured</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 12l2 2 4-4m5.5 2a9.5 9.5 0 11-19 0 9.5 9.5 0 0119 0z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Verified Chauffeurs</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 10h18M5 6h14a2 2 0 012 2v10a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Secure Payments</span></span>
      </div>
      <div class="cruise-badge-slot">
        <span class="cruise-badge cruise-badge--active"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="1.6" fill="none"/><path d="M12 6v6l4 2" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">24/7 Service</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13 2L3 14h7l-1 8 10-12h-7l1-8z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Fast Response</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 22s8-4 8-12V5l-8-3-8 3v5c0 8 8 12 8 12z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">100% Safe</span></span>
      </div>
      <div class="cruise-badge-slot">
        <span class="cruise-badge cruise-badge--active"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l3 7 7 .6-5.3 4.6L18.6 22 12 18l-6.6 4 1.9-7.2L2 9.6 9 9l3-7z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">5-Star Rated</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2M12 11a4 4 0 100-8 4 4 0 000 8z" stroke="currentColor" stroke-width="1.6" fill="none"/></svg><span class="badge-text">Expert Chauffeurs</span></span>
        <span class="cruise-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l2.5 5.5L20 8.5l-4 4 1 5.5-5-3-5 3 1-5.5-4-4 5.5-1L12 2z" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linejoin="round"/></svg><span class="badge-text">Premium Quality</span></span>
      </div>
      {% endif %}
    </div>

    <!-- Kicker -->
    <div class="kicker" data-step="2">{% if current_lang == 'es' %}BIENVENIDO A{% else %}WELCOME TO{% endif %}</div>

    <!-- Title -->
    <h1 class="title" data-step="3">
      <span class="title-text" data-text="CRUISE">CRUISE</span>
    </h1>

    <!-- Divider -->
    <div class="dividerX" data-step="4" aria-hidden="true">
      <span class="dividerX__line dividerX__line--left"></span>
      <span class="dividerX__diamond"></span>
      <span class="dividerX__line dividerX__line--right"></span>
    </div>

    <!-- Rotator -->
    <div class="rotator" data-step="5">
      {% if current_lang == 'es' %}
      <div class="rotator__slide is-active" data-slide="0"><div class="subtitle">TRANSPORTE DE LUJO</div><p class="desc">Experimenta una comodidad sin igual con nuestra flota premium de Chevrolet Suburban. Choferes profesionales, servicio impecable y atenci&oacute;n a cada detalle.</p></div>
      <div class="rotator__slide" data-slide="1"><div class="subtitle">SERVICIO 24/7</div><p class="desc">Disponibles d&iacute;a y noche con respuesta en minutos. Reserva cuando quieras, donde quieras &mdash; tu comodidad nunca descansa.</p></div>
      <div class="rotator__slide" data-slide="2"><div class="subtitle">CHOFERES ELITE</div><p class="desc">Profesionales certificados con a&ntilde;os de experiencia. Discreci&oacute;n, puntualidad y servicio de cinco estrellas garantizado.</p></div>
      <div class="rotator__slide" data-slide="3"><div class="subtitle">FLOTA PREMIUM</div><p class="desc">Chevrolet Suburban &uacute;ltimo modelo, interior de lujo y tecnolog&iacute;a de punta. Cada viaje es una experiencia excepcional.</p></div>
      {% else %}
      <div class="rotator__slide is-active" data-slide="0"><div class="subtitle">Ride in Luxury</div><p class="desc">Experience unparalleled comfort with our premium Chevrolet Suburban fleet. Professional chauffeurs, impeccable service, and attention to every detail.</p></div>
      <div class="rotator__slide" data-slide="1"><div class="subtitle">24/7 Service</div><p class="desc">Available day and night with response in minutes. Book whenever, wherever &mdash; your comfort never rests.</p></div>
      <div class="rotator__slide" data-slide="2"><div class="subtitle">Elite Chauffeurs</div><p class="desc">Certified professionals with years of experience. Discretion, punctuality, and five-star service guaranteed.</p></div>
      <div class="rotator__slide" data-slide="3"><div class="subtitle">Premium Fleet</div><p class="desc">Latest-model Chevrolet Suburban, luxury interior and cutting-edge tech. Every ride is an exceptional experience.</p></div>
      {% endif %}
    </div>

    <!-- CTA -->
    <div class="cta" data-step="6">
      <a class="btn btn-primary" href="{% if current_lang == 'es' %}/es{% endif %}/products/vip-service">
        <span class="btn-text">{% if current_lang == 'es' %}Reservar Ahora{% else %}Book Now{% endif %}</span>
        <span class="btn-shine"></span>
      </a>
    </div>

    <!-- App Download -->
    <div class="app-download" data-step="7">
      <span class="app-download__label">{% if current_lang == 'es' %}Proximamente en{% else %}Coming Soon to{% endif %}</span>
      <div class="app-download__buttons">
        <a class="store-btn store-btn--apple" href="#" target="_blank" rel="noopener noreferrer" aria-label="App Store">
          <span class="store-btn__badge">COMING SOON</span>
          <svg class="store-btn__icon" viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M18.71 19.5c-.83 1.24-1.71 2.45-3.05 2.47-1.34.03-1.77-.79-3.29-.79-1.53 0-2 .77-3.27.82-1.31.05-2.3-1.32-3.14-2.53C4.25 17 2.94 12.45 4.7 9.39c.87-1.52 2.43-2.48 4.12-2.51 1.28-.02 2.5.87 3.29.87.78 0 2.26-1.07 3.8-.91.65.03 2.47.26 3.64 1.98-.09.06-2.17 1.28-2.15 3.81.03 3.02 2.65 4.03 2.68 4.04-.03.07-.42 1.44-1.38 2.83M13 3.5c.73-.83 1.94-1.46 2.94-1.5.13 1.17-.34 2.35-1.04 3.19-.69.85-1.83 1.51-2.95 1.42-.15-1.15.41-2.35 1.05-3.11z"/></svg>
          <div class="store-btn__text">
            <span class="store-btn__small">{% if current_lang == 'es' %}Desc&aacute;rgalo en{% else %}Download on the{% endif %}</span>
            <span class="store-btn__big">App Store</span>
          </div>
        </a>
        <a class="store-btn store-btn--google" href="#" target="_blank" rel="noopener noreferrer" aria-label="Google Play">
          <span class="store-btn__badge">COMING SOON</span>
          <svg class="store-btn__icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3.61 1.814L13.793 12 3.61 22.186a.996.996 0 0 1-.61-.92V2.734a1 1 0 0 1 .61-.92z" fill="#4285F4"/><path d="M16.777 8.985L5.236.658C4.756.37 4.198.283 3.68.406l10.11 10.11 2.987-1.531z" fill="#EA4335"/><path d="M16.777 15.015L13.79 13.484 3.68 23.594c.518.123 1.076.036 1.556-.252l11.541-8.327z" fill="#34A853"/><path d="M20.243 10.836l-3.466-1.851L13.79 12l2.987 2.985 3.466-1.85c.68-.39.68-1.91 0-2.3z" fill="#FBBC04"/></svg>
          <div class="store-btn__text">
            <span class="store-btn__small">{% if current_lang == 'es' %}DISPONIBLE EN{% else %}GET IT ON{% endif %}</span>
            <span class="store-btn__big">Google Play</span>
          </div>
        </a>
      </div>
    </div>
  </div>
</section>

<style>
#cruiseHero-{{ section.id }}{
  --gold0:#fff4c4;--gold1:#f5d77a;--gold2:#d4af37;--gold3:#b98d1c;--gold4:#8a6610;
  --accent:var(--gold2);
  --ease-out-expo:cubic-bezier(.16,1,.3,1);--ease-out-quart:cubic-bezier(.25,1,.5,1);
  --ease-spring:cubic-bezier(.22,1.36,.36,1);--ease-material:cubic-bezier(.4,0,.2,1);
  position:relative;min-height:80vh;display:flex;align-items:center;justify-content:center;
  padding:140px 20px 80px;background:transparent!important;color:#fff;
  font-family:"Inter",sans-serif;overflow:hidden;
  -webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;
}
/* El hero es visible inmediatamente - las animaciones keyframes manejan las entradas */
#cruiseHero-{{ section.id }}.hero-ready [data-step]{will-change:transform,opacity;backface-visibility:hidden;}
#cruiseHero-{{ section.id }} .cruise-wrap{text-align:center;max-width:1000px;position:relative;margin:0 auto;width:100%;}
#cruiseHero-{{ section.id }} [data-step],#cruiseHero-{{ section.id }} .btn,#cruiseHero-{{ section.id }} .store-btn{will-change:transform,opacity;backface-visibility:hidden;transform:translateZ(0);}
#cruiseHero-{{ section.id }} [data-step]{opacity:0;visibility:hidden;}

@keyframes heroBadgesIn{0%{opacity:0;transform:translateY(14px) scale(.97);}100%{opacity:1;transform:translateY(0) scale(1);}}
@keyframes heroKickerIn{0%{opacity:0;letter-spacing:.8em;}100%{opacity:1;letter-spacing:.45em;}}
@keyframes heroTitleIn{0%{opacity:0;transform:scale(.88);filter:blur(8px);}55%{filter:blur(0);}78%{transform:scale(1.015);}100%{opacity:1;transform:scale(1);filter:blur(0);}}
@keyframes heroDrawLine{0%{transform:scaleX(0);}100%{transform:scaleX(1);}}
@keyframes heroDiamond{0%{transform:rotate(45deg) scale(0);}70%{transform:rotate(45deg) scale(1.08);}100%{transform:rotate(45deg) scale(1);}}
@keyframes heroRotatorIn{0%{opacity:0;transform:translateY(10px);}100%{opacity:1;transform:translateY(0);}}
@keyframes heroCtaIn{0%{opacity:0;transform:translateY(16px) scale(.96);}60%{transform:translateY(-2px) scale(1.01);}80%{transform:translateY(1px) scale(.998);}100%{opacity:1;transform:translateY(0) scale(1);}}
@keyframes heroStoreLeft{0%{opacity:0;transform:translateX(-14px) scale(.97);}100%{opacity:1;transform:translateX(0) scale(1);}}
@keyframes heroStoreRight{0%{opacity:0;transform:translateX(14px) scale(.97);}100%{opacity:1;transform:translateX(0) scale(1);}}
@keyframes heroAppLabelIn{0%{opacity:0;transform:translateY(6px);}100%{opacity:.9;transform:translateY(0);}}
@keyframes badgeFloat{0%,100%{transform:translate(-50%,-50%);}50%{transform:translate(-50%,calc(-50% - 2px));}}

/* Animaciones automaticas al cargar - sin depender del scroll */
#cruiseHero-{{ section.id }} [data-step="1"]{visibility:visible;animation:heroBadgesIn 1000ms var(--ease-out-expo) 0ms both;}
#cruiseHero-{{ section.id }} [data-step="2"]{visibility:visible;animation:heroKickerIn 1100ms var(--ease-out-expo) 200ms both;}
#cruiseHero-{{ section.id }} [data-step="3"]{visibility:visible;animation:heroTitleIn 1400ms var(--ease-spring) 450ms both;}
#cruiseHero-{{ section.id }} [data-step="4"]{visibility:visible;opacity:1;}
#cruiseHero-{{ section.id }} [data-step="4"] .dividerX__line--left{animation:heroDrawLine 900ms var(--ease-out-expo) 850ms both;}
#cruiseHero-{{ section.id }} [data-step="4"] .dividerX__line--right{animation:heroDrawLine 900ms var(--ease-out-expo) 950ms both;}
#cruiseHero-{{ section.id }} [data-step="4"] .dividerX__diamond{animation:heroDiamond 850ms var(--ease-spring) 1100ms both;}
#cruiseHero-{{ section.id }} [data-step="5"]{visibility:visible;animation:heroRotatorIn 1100ms var(--ease-out-quart) 1300ms both;}
#cruiseHero-{{ section.id }} [data-step="6"]{visibility:visible;animation:heroCtaIn 1100ms var(--ease-spring) 1700ms both;}
#cruiseHero-{{ section.id }} [data-step="7"]{visibility:visible;opacity:1;}
#cruiseHero-{{ section.id }} [data-step="7"] .app-download__label{animation:heroAppLabelIn 600ms var(--ease-out-expo) 2100ms both;}
#cruiseHero-{{ section.id }} .store-btn--apple{animation:heroStoreLeft 650ms var(--ease-out-expo) 2300ms both;}
#cruiseHero-{{ section.id }} .store-btn--google{animation:heroStoreRight 650ms var(--ease-out-expo) 2450ms both;}
#cruiseHero-{{ section.id }} .cruise-badge-slot:nth-child(1) .cruise-badge--active{animation:badgeFloat 3.5s ease-in-out 2.2s infinite;}
#cruiseHero-{{ section.id }} .cruise-badge-slot:nth-child(2) .cruise-badge--active{animation:badgeFloat 3.5s ease-in-out 2.4s infinite;}
#cruiseHero-{{ section.id }} .cruise-badge-slot:nth-child(3) .cruise-badge--active{animation:badgeFloat 3.5s ease-in-out 2.6s infinite;}

/* Badges */
#cruiseHero-{{ section.id }} .cruise-badges{display:flex;justify-content:center;gap:16px;margin-bottom:30px;flex-wrap:wrap;align-items:center;width:100%;padding:0 10px;}
#cruiseHero-{{ section.id }} .cruise-badge-slot{position:relative;display:inline-flex;align-items:center;justify-content:center;height:42px;flex:0 0 auto;min-width:210px;transition:width 600ms var(--ease-material);}
#cruiseHero-{{ section.id }} .cruise-badge{
  display:inline-flex;align-items:center;gap:8px;padding:10px 24px;white-space:nowrap;
  border:1px solid rgba(232,197,95,.42);border-radius:60px;
  font-size:12.5px;font-weight:500;letter-spacing:.02em;line-height:1;
  background:linear-gradient(135deg,rgba(30,25,10,.85) 0%,rgba(15,12,5,.9) 100%);
  box-shadow:0 7px 20px rgba(0,0,0,.5),0 0 0 1px rgba(232,197,95,.1) inset,inset 0 1px 0 rgba(255,235,170,.14),0 0 18px rgba(212,175,55,.1);
  color:rgba(255,255,255,.96);transition:opacity 900ms cubic-bezier(.4,0,.2,1);
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  opacity:0;pointer-events:none;
}
#cruiseHero-{{ section.id }} .cruise-badge--active{opacity:1;pointer-events:auto;z-index:2;}
#cruiseHero-{{ section.id }} .cruise-badge.cv-leaving{opacity:0;pointer-events:none;z-index:1;}
#cruiseHero-{{ section.id }} .cruise-badge svg{width:17px;height:17px;color:var(--gold1);flex-shrink:0;transition:transform 400ms var(--ease-spring);filter:drop-shadow(0 0 4px rgba(232,197,95,.4));}

/* Kicker & Title */
#cruiseHero-{{ section.id }} .kicker{letter-spacing:.45em;font-size:12px;color:var(--accent);margin-bottom:15px;text-transform:uppercase;font-weight:500;}
#cruiseHero-{{ section.id }} .title{position:relative;display:inline-block;margin:0;overflow:visible;line-height:1;}
#cruiseHero-{{ section.id }} .title-text{
  position:relative;z-index:3;display:inline-block;
  font-family:"Cinzel",serif;font-size:clamp(60px,8vw,120px);font-weight:900;letter-spacing:5px;
  text-transform:uppercase;
  background:linear-gradient(180deg,#fff4c4 0%,#f5d77a 28%,#d4af37 55%,#b98d1c 78%,#8a6610 100%);
  -webkit-background-clip:text;background-clip:text;
  -webkit-text-fill-color:transparent;color:transparent;
  will-change:filter,transform;transform:translateZ(0);backface-visibility:hidden;
}

/* Divider */
#cruiseHero-{{ section.id }} .dividerX{display:flex;align-items:center;justify-content:center;gap:14px;margin-top:22px;}
#cruiseHero-{{ section.id }} .dividerX__line{height:1px;width:100px;background:linear-gradient(to right,transparent,var(--accent),transparent);transform-origin:center;transform:scaleX(0);box-shadow:0 0 8px rgba(212,175,55,.3);}
#cruiseHero-{{ section.id }} .dividerX__diamond{width:10px;height:10px;background:linear-gradient(135deg,var(--gold1),var(--gold2),var(--gold3));transform:rotate(45deg) scale(0);box-shadow:0 0 16px rgba(212,175,55,.7),0 0 32px rgba(212,175,55,.35);}

/* Rotator */
#cruiseHero-{{ section.id }} .rotator{position:relative;margin-top:26px;min-height:170px;max-width:720px;margin-inline:auto;}
#cruiseHero-{{ section.id }} .rotator__slide{position:absolute;inset:0;opacity:0;pointer-events:none;transition:opacity 650ms var(--ease-material),transform 650ms var(--ease-material);transform:translateY(8px);will-change:opacity,transform;}
#cruiseHero-{{ section.id }} .rotator__slide.is-active{opacity:1;pointer-events:auto;transform:translateY(0);}
#cruiseHero-{{ section.id }} .rotator__slide.is-leaving{opacity:0;transform:translateY(-8px);pointer-events:none;}
#cruiseHero-{{ section.id }} .subtitle{letter-spacing:6px;text-transform:uppercase;font-family:"Cinzel",serif;font-size:18px;color:var(--gold1);text-shadow:0 2px 16px rgba(0,0,0,.7);}
#cruiseHero-{{ section.id }} .desc{margin-top:22px;max-width:700px;margin-inline:auto;line-height:1.85;font-size:15px;font-weight:300;color:rgba(255,255,255,.88);text-shadow:0 2px 14px rgba(0,0,0,.85);letter-spacing:.01em;}

/* CTA */
#cruiseHero-{{ section.id }} .cta{margin-top:35px;}
#cruiseHero-{{ section.id }} .btn{display:inline-flex;align-items:center;justify-content:center;height:52px;padding:0 32px;border-radius:14px;text-decoration:none;font-weight:800;letter-spacing:.18em;font-size:12px;text-transform:uppercase;position:relative;overflow:hidden;border:none;cursor:pointer;}
#cruiseHero-{{ section.id }} .btn-primary{
  background:linear-gradient(135deg,#f8e29a 0%,#e8c56a 22%,#d4af37 50%,#b98d1c 78%,#9a7514 100%);
  color:#1a1208;border:1px solid rgba(255,225,140,.8);
  box-shadow:0 8px 24px rgba(0,0,0,.45),0 0 0 1px rgba(212,175,55,.25),0 0 30px rgba(212,175,55,.15),inset 0 1.5px 0 rgba(255,255,255,.55),inset 0 -1.5px 0 rgba(100,70,10,.4),inset 0 0 0 1px rgba(255,215,120,.3);
  transition:transform 400ms var(--ease-spring),box-shadow 600ms var(--ease-out-quart),filter 400ms var(--ease-out-quart);
}
#cruiseHero-{{ section.id }} .btn-text{position:relative;z-index:2;transition:transform 350ms var(--ease-out-quart),letter-spacing 350ms var(--ease-out-quart);text-shadow:0 1px 0 rgba(255,235,170,.4);}
#cruiseHero-{{ section.id }} .btn-shine{position:absolute;inset:0;background:linear-gradient(90deg,transparent 0%,rgba(255,255,255,.45) 50%,transparent 100%);transform:translateX(-100%);transition:transform 700ms var(--ease-out-expo);}
@media(hover:hover) and (pointer:fine){
  #cruiseHero-{{ section.id }} .btn-primary:hover{transform:translateY(-3px) scale(1.03);box-shadow:0 18px 44px rgba(0,0,0,.55),0 0 0 2px rgba(245,215,122,.4),0 0 50px rgba(245,215,122,.25),inset 0 1.5px 0 rgba(255,255,255,.65),inset 0 -1.5px 0 rgba(100,70,10,.4),inset 0 0 0 1px rgba(255,215,120,.4);filter:saturate(1.12) brightness(1.06);}
  #cruiseHero-{{ section.id }} .btn-primary:hover .btn-shine{transform:translateX(100%);}
  #cruiseHero-{{ section.id }} .btn-primary:hover .btn-text{transform:scale(1.04);letter-spacing:.22em;}
}
#cruiseHero-{{ section.id }} .btn-primary:active{transform:translateY(0) scale(.97);box-shadow:0 4px 12px rgba(0,0,0,.4),0 0 0 1px rgba(212,175,55,.25),inset 0 2px 4px rgba(60,40,5,.3);transition-duration:100ms;}

