  background:linear-gradient(135deg,#d4af37,#b98d1c);
  color:#0a0a0a;font-size:8px;font-weight:800;letter-spacing:.1em;
  text-transform:uppercase;padding:3px 8px;border-radius:10px;
  border:1px solid rgba(255,255,255,.25);
  box-shadow:0 2px 8px rgba(212,175,55,.3);
  z-index:10;pointer-events:none;
