  /* Reducir espaciados para que todo quepa sin scroll */
  #cruiseHero-{{ section.id }} .cta{margin-top:28px;}
  #cruiseHero-{{ section.id }} .app-download{margin-top:36px;}
  #cruiseHero-{{ section.id }} .dividerX{margin-top:18px;}
