  #cruiseHero-{{ section.id }} .cruise-badge{font-size:9.5px;padding:6px 12px;gap:5px;}
  #cruiseHero-{{ section.id }} .cruise-badge svg{width:11px;height:11px;}
  #cruiseHero-{{ section.id }} .title-text{font-size:clamp(40px,11vw,60px);}
  #cruiseHero-{{ section.id }} .subtitle{font-size:12px;letter-spacing:3px;}
  #cruiseHero-{{ section.id }} .desc{font-size:13px;line-height:1.7;}
  #cruiseHero-{{ section.id }} .btn{height:46px;padding:0 24px;font-size:11px;}
