<script>
/* ============================================================
   CRUISE HERO - INICIO AUTOMATICO, SIN DEPENDENCIA DE SCROLL
   Las animaciones CSS keyframes se ejecutan al cargar la pagina.
   Este JS solo gestiona los rotadores (badges y slides).
   ============================================================ */
(function(){
  var root=document.getElementById('cruiseHero-{{ section.id }}');
  if(!root) return;
  var __slotsCache=null;

  /* --- Badge slot sizing --- */
  function __measureAllSlots(){
    __slotsCache=__slotsCache||root.querySelectorAll('.cruise-badge-slot');
    __slotsCache.forEach(function(slot){
      var badges=slot.querySelectorAll('.cruise-badge'),max=0;
      badges.forEach(function(b){
        var clone=b.cloneNode(true);
        clone.style.cssText='position:absolute;left:-9999px;top:0;opacity:0;transform:none;pointerEvents:none;display:inline-flex;';
        document.body.appendChild(clone);
        var w=clone.offsetWidth;
        document.body.removeChild(clone);
        if(w>max) max=w;
      });
      if(max>0){
        var currentMin=parseFloat(getComputedStyle(slot).minWidth)||0;
        slot.style.width=Math.max(max+24,currentMin)+'px';
      }
    });
  }

  /* Ejecuta inmediatamente y en multiples momentos para asegurar fonts cargadas */
  __measureAllSlots();
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',__measureAllSlots);
  }
  if(document.fonts&&document.fonts.ready) document.fonts.ready.then(__measureAllSlots);
  window.addEventListener('load',__measureAllSlots);
  [300,800,2000,4000].forEach(function(t){setTimeout(__measureAllSlots,t);});
  window.addEventListener('resize',__measureAllSlots,{passive:true});

  /* --- Rotador de badges --- */
  function startBadgeRotator(){
    var slots=root.querySelectorAll('.cruise-badge-slot');
    __measureAllSlots();
    var reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(reduced) return;
    var INTERVAL=6000,STAGGER=1100;
    slots.forEach(function(slot,slotIdx){
      var badges=slot.querySelectorAll('.cruise-badge');
      if(badges.length<2) return;
      var idx=0;
      setTimeout(function(){
        setInterval(function(){
          var current=badges[idx];
          idx=(idx+1)%badges.length;
          var incoming=badges[idx];
          current.classList.remove('cruise-badge--active');
          current.classList.add('cv-leaving');
          incoming.classList.add('cruise-badge--active');
          setTimeout(function(){current.classList.remove('cv-leaving');},950);
        },INTERVAL);
      },4000+slotIdx*STAGGER);
    });
  }

  /* --- Rotador de slides --- */
  function startRotator(){
    var slides=root.querySelectorAll('.rotator__slide');
    if(slides.length<2) return;
    var reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(reduced) return;
    var idx=0,INTERVAL=5000;
    function next(){
      var current=slides[idx];
      idx=(idx+1)%slides.length;
      var incoming=slides[idx];
      current.classList.remove('is-active');
      current.classList.add('is-leaving');
      incoming.classList.remove('is-leaving');
      incoming.classList.add('is-active');
      setTimeout(function(){current.classList.remove('is-leaving');},700);
    }
    setInterval(next,INTERVAL);
  }

  /* --- Inicio inmediato de rotadores (sin esperar scroll) --- */
  function initRotators(){
    startRotator();
    startBadgeRotator();
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',initRotators);
  } else {
    initRotators();
  }
  /* Fallback: si el DOM tarda, fuerza a los 3 segundos */
  setTimeout(initRotators,3000);

  /* --- Prefetch del boton de reserva --- */
  var reserveBtn=root.querySelector('.btn-primary');
  if(reserveBtn){
    var href=reserveBtn.getAttribute('href');
    if(href){
      try{var link=document.createElement('link');link.rel='prefetch';link.href=href;link.as='document';document.head.appendChild(link);}catch(e){}
      var prefetchOnHover=function(){
        try{if(reserveBtn.hasAttribute('data-prefetched')) return;reserveBtn.setAttribute('data-prefetched','1');var l=document.createElement('link');l.rel='prerender';l.href=href;document.head.appendChild(l);}catch(e){}
      };
      reserveBtn.addEventListener('mouseenter',prefetchOnHover,{passive:true});
      reserveBtn.addEventListener('touchstart',prefetchOnHover,{passive:true});
    }
  }
})();
</script>

