<style>
/* ============================================================
   SECCION: Sin min-height forzado, padding reducido
   para conectar arriba y abajo sin espacios
   ============================================================ */
.contact-minimal{
  position: relative;
  width: 100%;
  min-height: 0;
  color: #fff;
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  padding: 50px 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: visible;
  box-sizing: border-box;
  background: transparent;
}

/* ===== FONDO VIDEO ===== */
.contact-minimal__bg{
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #000;
  overflow: hidden;
}

.contact-minimal__video{
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ===== OVERLAY: gradiente que SE FUNDEN con secciones vecinas =====
   Arriba: negro puro (0-8%) que se desvanece rapido - se funde con la seccion anterior
   Centro: velo ligero para legibilidad
   Abajo: negro puro (0-8%) que se desvanece rapido - se funde con la siguiente seccion */
.contact-minimal__overlay{
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    /* Gradiente superior: se funde CON LA SECCION DE ARRIBA */
    linear-gradient(to bottom, 
      rgba(0,0,0, 0.92) 0%, 
      rgba(0,0,0, 0.70) 5%, 
      rgba(0,0,0, 0.35) 15%, 
      rgba(0,0,0, 0.10) 28%, 
      transparent 40%
    ),
    /* Gradente inferior: se funde CON LA SECCION DE ABAJO */
    linear-gradient(to top, 
      rgba(0,0,0, 0.92) 0%, 
      rgba(0,0,0, 0.70) 5%, 
      rgba(0,0,0, 0.35) 15%, 
      rgba(0,0,0, 0.10) 28%, 
      transparent 40%
    ),
    /* Velo central muy ligero */
    rgba(0,0,0, 0.20);
  pointer-events: none;
}

/* ===== CONTENIDO ===== */
.contact-minimal__inner{
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  z-index: 2;
  width: 100%;
}

/* ===== ANIMACION ===== */
[data-reveal]{
  opacity: 0;
  transform: translateY(30px);
  filter: blur(3px);
  transition: opacity .65s cubic-bezier(.16,1,.3,1),
              transform .65s cubic-bezier(.16,1,.3,1),
              filter .65s cubic-bezier(.16,1,.3,1);
  will-change: opacity, transform, filter;
}

[data-reveal].is-visible{
  opacity: 1;
  transform: translateY(0);
  filter: blur(0);
}

/* ===== HEADER ===== */
.contact-minimal__header{
  text-align: center;
  margin-bottom: 35px;
}

.contact-minimal__eyebrow{
  display: block;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: .25em;
  text-transform: uppercase;
  color: #d4af37 !important;
  margin-bottom: 10px;
}

.contact-minimal__title{
  font-family: "Cinzel", serif;
  font-size: clamp(26px, 5vw, 44px);
  font-weight: 400;
  line-height: 1.2;
  margin: 0 0 10px;
  color: #fff;
}

.contact-minimal__title em{
  font-style: normal;
  color: #d4af37;
}

.contact-minimal__lead{
  font-size: 14px;
  font-weight: 300;
  color: #fff;
  margin: 0 auto;
  line-height: 1.5;
  max-width: 420px;
  opacity: .55;
}

/* ===== GRID ===== */
.contact-minimal__grid{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  align-items: stretch;
}

/* ===== INFO / FORM ===== */
.contact-minimal__info-wrap,
.contact-minimal__form-wrap{
  background: rgba(0,0,0, .50);
  border: 1px solid rgba(212,175,55, .10);
  border-radius: 18px;
  padding: 28px 24px;
  backdrop-filter: blur(10px);
}

.contact-minimal__info{
  display: flex;
  flex-direction: column;
}

.info-item{
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 16px 0;
}

.info-item:first-child{ padding-top: 0; }
.info-item:last-child{ padding-bottom: 0; }

.info-divider{
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(212,175,55,.15), transparent);
  margin-left: 38px;
}

.info-item__icon{
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  border: 1px solid rgba(212,175,55, .22);
  color: #d4af37;
  display: flex;
  align-items: center;
  justify-content: center;
}

.info-item__body{
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.info-item__label{
  font-size: 10px;
  font-weight: 500;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: #d4af37 !important;
}

.info-item__value,
.info-item__value:link,
.info-item__value:visited{
  font-size: 14px;
  font-weight: 400;
  color: #ffffff !important;
  text-decoration: none;
  letter-spacing: .01em;
  transition: opacity .3s ease;
  word-break: break-word;
}

.info-item__value:hover{
  opacity: .75;
  color: #ffffff !important;
}

.info-item__value--large{
  font-family: "Cinzel", serif;
  font-size: 18px;
  color: #ffffff !important;
  letter-spacing: .05em;
}

.info-item__meta{
  font-size: 11px;
  color: #ffffff !important;
  opacity: .4;
  font-weight: 300;
}

/* Actions */
.info-item__action{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 5px;
  padding: 5px 11px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 500;
  text-decoration: none;
  border: none;
  cursor: pointer;
  width: fit-content;
  transition: all .25s ease;
}

.info-item__action--primary{
  background: #25D366 !important;
  color: #ffffff !important;
}

.info-item__action--primary svg{
  color: #ffffff !important;
  fill: #ffffff !important;
}

.info-item__action--primary:hover{
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(37,211,102, .25);
  color: #ffffff !important;
}

.info-item__action--ghost{
  background: transparent;
  border: 1px solid rgba(212,175,55, .28);
  color: #d4af37;
}

.info-item__action--ghost:hover{
  border-color: rgba(212,175,55, .7);
  background: rgba(212,175,55, .08);
  color: #fff;
}

/* ===== FORM ===== */
.contact-minimal__form{
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.form-row{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.form-field{
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.form-field__label{
  font-size: 10px;
  font-weight: 500;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #d4af37 !important;
}

.form-field__input,
.form-field__textarea{
  width: 100%;
  background: rgba(0,0,0, .30);
  border: 1px solid rgba(212,175,55, .22);
  border-radius: 10px;
  padding: 11px 13px;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  caret-color: #d4af37;
  font-family: inherit;
  font-size: 14px;
  outline: none;
  transition: border-color .3s ease, background .3s ease, box-shadow .3s ease;
  box-sizing: border-box;
  box-shadow: inset 0 0 0 100px rgba(0,0,0, .30);
}

.form-field__input::placeholder,
.form-field__textarea::placeholder{
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  opacity: .4;
}

.form-field__input:focus,
.form-field__textarea:focus{
  border-color: rgba(212,175,55, .7);
  background: rgba(0,0,0, .45);
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  box-shadow: inset 0 0 0 100px rgba(0,0,0, .45), 0 0 0 3px rgba(212,175,55, .08);
}

.form-field__input:-webkit-autofill,
.form-field__input:-webkit-autofill:hover,
.form-field__input:-webkit-autofill:focus,
.form-field__textarea:-webkit-autofill,
.form-field__textarea:-webkit-autofill:hover,
.form-field__textarea:-webkit-autofill:focus{
  -webkit-text-fill-color: #ffffff !important;
  -webkit-box-shadow: inset 0 0 0 100px rgba(0,0,0, .45) !important;
  box-shadow: inset 0 0 0 100px rgba(0,0,0, .45) !important;
  transition: background-color 5000s ease-in-out 0s;
  caret-color: #d4af37;
  border-color: rgba(212,175,55, .7);
}

.form-field__textarea{
  resize: vertical;
  min-height: 70px;
  line-height: 1.5;
}

.contact-minimal__submit{
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  padding: 12px;
  margin-top: 2px;
  border: 1px solid rgba(212,175,55, .28);
  border-radius: 12px;
  background: transparent;
  color: #fff;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: .02em;
  cursor: pointer;
  transition: all .3s ease;
}

.contact-minimal__submit:hover,
.contact-minimal__submit:active{
  background: #d4af37;
  color: #0a0a0a;
  border-color: #d4af37;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(212,175,55, .25);
}

/* ===== TABLET ===== */
@media (max-width: 900px){
  .contact-minimal__grid{
    grid-template-columns: 1fr;
    gap: 16px;
    max-width: 520px;
    margin-inline: auto;
  }
  .contact-minimal__info-wrap,
  .contact-minimal__form-wrap{
    padding: 22px 18px;
  }
}

/* ===== MOVIL ===== */
@media (max-width: 640px){
  .contact-minimal{
    padding: 30px 16px;
  }

  .contact-minimal__header{ margin-bottom: 16px; }
  .contact-minimal__eyebrow{ font-size: 9px; letter-spacing: .2em; margin-bottom: 5px; }
  .contact-minimal__title{ font-size: clamp(20px, 7vw, 26px); line-height: 1.15; margin-bottom: 5px; }
  .contact-minimal__lead{ font-size: 12px; max-width: 100%; line-height: 1.4; opacity: .6; }

  .contact-minimal__grid{
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .contact-minimal__info-wrap,
  .contact-minimal__form-wrap{
    padding: 14px 12px;
    border-radius: 14px;
    background: rgba(0,0,0, .55);
    backdrop-filter: blur(8px);
  }

  .info-item{ padding: 8px 0; gap: 8px; }
  .info-item__icon{ width: 26px; height: 26px; border-radius: 8px; }
  .info-item__icon svg{ width: 13px; height: 13px; }
  .info-item__value{ font-size: 12px; }
  .info-item__value--large{ font-size: 15px; }
  .info-item__label{ font-size: 8px; letter-spacing: .12em; }
  .info-item__meta{ font-size: 10px; }
  .info-divider{ margin-left: 34px; }
  .info-item__action{ font-size: 10px; padding: 4px 9px; margin-top: 3px; }

  .contact-minimal__form{ gap: 9px; }
  .form-row{ grid-template-columns: 1fr; gap: 9px; }

  .form-field__label{ font-size: 8px; letter-spacing: .08em; }
  .form-field__input,
  .form-field__textarea{
    padding: 9px 10px;
    font-size: 12px;
    border-radius: 8px;
    box-shadow: inset 0 0 0 100px rgba(0,0,0, .35);
  }
  .form-field__textarea{ min-height: 55px; resize: none; }

  .form-field__input:focus,
  .form-field__textarea:focus{
    box-shadow: inset 0 0 0 100px rgba(0,0,0, .50), 0 0 0 3px rgba(212,175,55, .08);
  }

  .contact-minimal__submit{
    padding: 11px;
    font-size: 12px;
    border-radius: 10px;
    margin-top: 3px;
  }
  .contact-minimal__submit .submit-icon{ width: 13px; height: 13px; }

  [data-reveal]{
    transform: translateY(18px);
    filter: blur(2px);
    transition-duration: .5s;
  }
}

/* ===== SMALL PHONES ===== */
@media (max-width: 380px){
  .contact-minimal{ padding: 24px 12px; }
  .contact-minimal__info-wrap,
  .contact-minimal__form-wrap{ padding: 12px 10px; border-radius: 12px; }
  .contact-minimal__title{ font-size: 18px; }
  .info-item{ gap: 7px; padding: 7px 0; }
  .info-item__icon{ width: 22px; height: 22px; }
  .info-item__value{ font-size: 11px; }
  .info-item__value--large{ font-size: 13px; }
  .form-field__input,
  .form-field__textarea{ padding: 8px 9px; font-size: 12px; }
  .contact-minimal__submit{ font-size: 12px; padding: 9px; }
}

/* REDUCED MOTION */
@media (prefers-reduced-motion: reduce){
  [data-reveal]{
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
    transition: none !important;
  }
}
</style>

<script>
(function(){
  var section = document.getElementById('contact-{{ section.id }}');
  if(!section) return;

  var video = section.querySelector('.contact-minimal__video');
  var reveals = section.querySelectorAll('[data-reveal]');

  /* VIDEO: autoplay inmediato */
  function forcePlay(){
    if(!video) return;
    video.play().catch(function(){
      document.addEventListener('touchstart', function(){
        video.play().catch(function(){});
      }, {once:true});
    });
  }

  forcePlay();
  if(video){
    video.addEventListener('loadeddata', forcePlay);
    video.addEventListener('canplay', forcePlay);
  }

  /* ANIMACIONES AUTOMATICAS: SIN SCROLL */
  function startRevealAnimations(){
    var orderedReveals = Array.from(reveals).sort(function(a, b){
      return parseInt(a.getAttribute('data-reveal') || '0') - parseInt(b.getAttribute('data-reveal') || '0');
    });

    orderedReveals.forEach(function(el, i){
      setTimeout(function(){
        el.classList.add('is-visible');
      }, 200 + i * 100);
    });
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', startRevealAnimations);
  } else {
    startRevealAnimations();
  }

  /* Copy email */
  window['copyEmail{{ section.id | replace: "-", "_" }}'] = function(btn){
    navigator.clipboard.writeText('SUPPORT@CRUISEINRIDE.COM').then(function(){
      var span = btn.querySelector('.copy-text');
      var original = span.textContent;
      var isEs = (section.getAttribute('data-lang') === 'es');
      span.textContent = isEs ? 'Copiado!' : 'Copied!';
      btn.style.borderColor = 'rgba(212,175,55,.7)';
      setTimeout(function(){
        span.textContent = original;
        btn.style.borderColor = '';
      }, 2000);
    });
  };
})();
</script>
